export function travelWorld(game,getDistricts){let enabled=false,current=null,journey=null,heat=0,vehicles=[],requests=new Map();const options={walk_seconds:120,train_seconds:45,drive_seconds:20,train_fare:50,drive_fuel:5,fuel_price:10};
const read=()=>{const districts=getDistricts();current??=districts.find(d=>d.slug==="the-waterfront")??districts[0];if(journey&&Date.parse(journey.arrives_at)<=Date.now()){current=districts.find(d=>d.id===journey.id);journey=null;heat=0;}return {enabled,season_id:game.season.id,server_time:new Date().toISOString(),jailed:false,current,journey,heat,vehicles,options,districts};};
return {read,setup:p=>{enabled=true;if(p.heat!==undefined)heat=p.heat;if(p.car)vehicles=[{id:"travel-car",name:"Dockside Sedan",fuel:0}];if(p.arrive&&journey)journey.arrives_at=new Date(0).toISOString();},action:(action,p)=>{read();const key=JSON.stringify({action,p});if(requests.has(p.request_id))return requests.get(p.request_id).key===key?requests.get(p.request_id).result:{error:"Request already used"};if(journey)return {error:"Finish your current journey first."};let car=vehicles.find(v=>v.id===p.vehicle_id),cost=0;if(action==="refuel"){if(!car||p.units<1||p.units+car.fuel>100)return {error:"Invalid refuel"};cost=p.units*options.fuel_price;if(game.player.cash<cost)return {error:"Not enough cash"};car.fuel+=p.units;}else{const d=getDistricts().find(d=>d.id===p.district_id);if(!d||d.id===current.id)return {error:"Choose another district"};if(p.method==="drive"){if(!car||car.fuel<5)return {error:"Not enough fuel"};car.fuel-=5;}if(p.method==="train")cost=50;if(game.player.cash<cost)return {error:"Not enough cash"};journey={...d,method:p.method,departed_at:new Date().toISOString(),arrives_at:new Date(Date.now()+options[p.method+"_seconds"]*1000).toISOString()};}game.player.cash-=cost;const result={message:action==="refuel"?"Vehicle refuelled.":"Journey started."};requests.set(p.request_id,{key,result});return result;}};}
